def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c

    last_me = me[-1] if n else 'C'
    last_opp = opp[-1] if n else 'C'

    # Small early probing / noise-like behavior, but avoid hurting clean reciprocal openings too much.
    if n < 3:
        if n == 0:
            return 'C'
        if last_opp == 'D' and rng.random() < 0.75:
            return 'D'
        return 'C'

    # Endgame: no future retaliation. Be more willing to exploit, especially vs cooperative histories.
    if n >= 96:
        if opp_d <= max(3, n // 20):
            if n >= 98:
                return 'D'
            if rng.random() < 0.8:
                return 'D'
        if last_opp == 'D':
            return 'D'
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # Persistent defector: defend hard, but keep occasional probes if they recently cooperated.
    if opp_d >= opp_c + 4 or (n >= 8 and opp_c <= 1):
        if last_opp == 'C' and opp_c >= 2 and rng.random() < 0.45:
            return 'C'
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    # Mostly cooperative opponent: keep cooperation flowing, with light probing and late exploitation.
    if opp_d == 0:
        if n < 12:
            return 'C'
        if rng.random() < 0.015:
            return 'D'
        return 'C'

    # Estimate recent behavior.
    recent_window = 8 if n >= 8 else n
    recent = history[-recent_window:]
    rec_cc = rec_cd = rec_dc = rec_dd = 0
    rec_opp_c = 0
    for a, b in recent:
        if b == 'C':
            rec_opp_c += 1
        if a == 'C' and b == 'C':
            rec_cc += 1
        elif a == 'C' and b == 'D':
            rec_cd += 1
        elif a == 'D' and b == 'C':
            rec_dc += 1
        else:
            rec_dd += 1

    rec_opp_d = recent_window - rec_opp_c

    # Recover from mutual defection spirals, but do so faster with a little probing.
    if rec_dd >= 3:
        if rng.random() < 0.7:
            return 'C'
        if last_opp == 'C':
            return 'C'
        return 'D'

    # If opponent is highly cooperative recently, cooperate, with rare low-cost tests.
    if rec_opp_d <= 1:
        if last_opp == 'D' and rec_opp_d == 1:
            # Mostly retaliate, but sometimes forgive one-off defections.
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        if rng.random() < 0.02:
            return 'D'
        return 'C'

    # Strong recent defection: retaliate, but don't lock in forever.
    if rec_opp_d >= 4:
        if last_opp == 'C' and rng.random() < 0.35:
            return 'C'
        if rec_dc >= 2 and rec_cc >= 1 and rng.random() < 0.25:
            return 'D'
        return 'D'

    # Main reciprocating logic.
    if last_opp == 'C':
        # If we recently exploited successfully, sometimes continue exploiting.
        if rec_dc >= 2 and rng.random() < 0.35:
            return 'D'
        return 'C'

    # Opponent defected last.
    if last_me == 'D':
        # In mutual punishment, occasionally offer cooperation to reset.
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # We cooperated, opponent defected: retaliate usually, but forgive sometimes if rare.
    if opp_d <= max(2, n // 12):
        if rng.random() < 0.35:
            return 'C'
        return 'D'
    if rng.random() < 0.12:
        return 'C'
    return 'D'
